mapper.select:
SELECT FROM device
AND name LIKE CONCAT('%', #{name}, '%')
AND status = #{status}
AND device_type_id = #{deviceTypeId}
AND location LIKE CONCAT('%', #{location}, '%')
ORDER BY created_at DESC

mapper.update:
UPDATE device
name = #{name}, device_type_id = #{deviceTypeId}, location = #{location}, status = #{status}, serial_number = #{serialNumber}, manufacturer = #{manufacturer}, purchase_date = #{purchaseDate}, warranty_expiry = #{warrantyExpiry}, description = #{description}, updated_at = #{updatedAt}
